private _pieceKey(i: number) {
  if (!this._board[i]) {
    return 0n
  }

  const { color, type } = this._board[i]

  const colorIndex = {
    w: 0,
    b: 1,
  }[color]

  const typeIndex = {
    p: 0,
    n: 1,
    b: 2,
    r: 3,
    q: 4,
    k: 5,
  }[type]

  return PIECE_KEYS[colorIndex][typeIndex][i]
}

private _epKey() {
  return this._epSquare === EMPTY ? 0n : EP_KEYS[this._epSquare & 7]
}

private _castlingKey() {
  const index = (this._castling.w >> 5) | (this._castling.b >> 3)
  return CASTLING_KEYS[index]
}

private _computeHash() {
  let hash = 0n

  for (let i = Ox88.a8; i <= Ox88.h1; i++) {
    // did we run off the end of the board
    if (i & 0x88) {
      i += 7
      continue
    }

    if (this._board[i]) {
      hash ^= this._pieceKey(i)
    }
  }

  hash ^= this._epKey()
  hash ^= this._castlingKey()

  if (this._turn === 'b') {
    hash ^= SIDE_KEY
  }

  return hash
}

/*
 * Called when the initial board setup is changed with put() or remove().
 * modifies the SetUp and FEN properties of the header object. If the FEN
 * is equal to the default position, the SetUp and FEN are deleted the setup
 * is only updated if history.length is zero, ie moves haven't been made.
 */
private _updateSetup(fen: string) {
  if (this._history.length > 0) return

  if (fen !== DEFAULT_POSITION) {
    this._header['SetUp'] = '1'
    this._header['FEN'] = fen
  } else {
    this._header['SetUp'] = null
    this._header['FEN'] = null
  }
}

reset() {
  this.load(DEFAULT_POSITION)
  this._comments = {}
  this._suffixes = {}
  this._nags = {}
}

get(square: Square): Piece | undefined {
  return this._board[Ox88[square]]
}

findPiece(piece: Piece): Square[] {
  const squares: Square[] = []
  for (let i = Ox88.a8; i <= Ox88.h1; i++) {
    // did we run off the end of the board
    if (i & 0x88) {
      i += 7
      continue
    }

    // if empty square or wrong color
    if (!this._board[i] || this._board[i]?.color !== piece.color) {
      continue
    }

    // check if square contains the requested piece
    if (
      this._board[i].color === piece.color &&
      this._board[i].type === piece.type
    ) {
      squares.push(algebraic(i))
    }
  }

  return squares
}

put(
  { type, color }: { type: PieceSymbol; color: Color },
  square: Square,
): boolean {
  if (this._put({ type, color }, square)) {
    this._updateCastlingRights()
    this._updateEnPassantSquare()
    this._updateSetup(this.fen())
    return true
  }
  return false
}

private _set(sq: number, piece: Piece) {
  this._hash ^= this._pieceKey(sq)
  this._board[sq] = piece
  this._hash ^= this._pieceKey(sq)
}

private _put(
  { type, color }: { type: PieceSymbol; color: Color },
  square: Square,
): boolean {
  // check for piece
  if (SYMBOLS.indexOf(type.toLowerCase()) === -1) {
    return false
  }

  // check for valid square
  if (!(square in Ox88)) {
    return false
  }

  const sq = Ox88[square]

  // don't let the user place more than one king
  if (
    type == KING &&
    !(this._kings[color] == EMPTY || this._kings[color] == sq)
  ) {
    return false
  }

  const currentPieceOnSquare = this._board[sq]

  // if one of the kings will be replaced by the piece from args, set the `_kings` respective entry to `EMPTY`
  if (currentPieceOnSquare && currentPieceOnSquare.type === KING) {
    this._kings[currentPieceOnSquare.color] = EMPTY
  }

  this._set(sq, { type: type as PieceSymbol, color: color as Color })

  if (type === KING) {
    this._kings[color] = sq
  }

  return true
}

private _clear(sq: number) {
  this._hash ^= this._pieceKey(sq)
  delete this._board[sq]
}

remove(square: Square): Piece | undefined {
  const piece = this.get(square)
  this._clear(Ox88[square])
  if (piece && piece.type === KING) {
    this._kings[piece.color] = EMPTY
  }

  this._updateCastlingRights()
  this._updateEnPassantSquare()
  this._updateSetup(this.fen())

  return piece
}

