      const castlingFrom = move.to - 2
      this._movePiece(castlingFrom, castlingTo)
    }

    // turn off castling
    this._castling[us] = 0
  }

  // turn off castling if we move a rook
  if (this._castling[us]) {
    for (let i = 0, len = ROOKS[us].length; i < len; i++) {
      if (
        move.from === ROOKS[us][i].square &&
        this._castling[us] & ROOKS[us][i].flag
      ) {
        this._castling[us] ^= ROOKS[us][i].flag
        break
      }
    }
  }

  // turn off castling if we capture a rook
  if (this._castling[them]) {
    for (let i = 0, len = ROOKS[them].length; i < len; i++) {
      if (
        move.to === ROOKS[them][i].square &&
        this._castling[them] & ROOKS[them][i].flag
      ) {
        this._castling[them] ^= ROOKS[them][i].flag
        break
      }
    }
  }

  this._hash ^= this._castlingKey()

  // if big pawn move, update the en passant square
  if (move.flags & BITS.BIG_PAWN) {
    let epSquare

    if (us === BLACK) {
      epSquare = move.to - 16
    } else {
      epSquare = move.to + 16
    }

    this._fenEpSquare = epSquare

    if (
      (!((move.to - 1) & 0x88) &&
        this._board[move.to - 1]?.type === PAWN &&
        this._board[move.to - 1]?.color === them) ||
      (!((move.to + 1) & 0x88) &&
        this._board[move.to + 1]?.type === PAWN &&
        this._board[move.to + 1]?.color === them)
    ) {
      this._epSquare = epSquare
      this._hash ^= this._epKey()
    } else {
      this._epSquare = EMPTY
    }
  } else {
    this._epSquare = EMPTY
    this._fenEpSquare = EMPTY
  }

  // reset the 50 move counter if a pawn is moved or a piece is captured
  if (move.piece === PAWN) {
    this._halfMoves = 0
  } else if (move.flags & (BITS.CAPTURE | BITS.EP_CAPTURE)) {
    this._halfMoves = 0
  } else {
    this._halfMoves++
  }

  if (us === BLACK) {
    this._moveNumber++
  }

  this._turn = them
  this._hash ^= SIDE_KEY
}

undo(): Move | null {
  const hash = this._hash
  const move = this._undoMove()
  if (move) {
    const prettyMove = this._createMove(move)
    this._decPositionCount(hash)
    return prettyMove
  }
  return null
}

private _undoMove(): InternalMove | null {
  const old = this._history.pop()
  if (old === undefined) {
    return null
  }

  this._hash ^= this._epKey()
  this._hash ^= this._castlingKey()

  const move = old.move

  this._kings = old.kings
  this._turn = old.turn
  this._castling = old.castling
  this._epSquare = old.epSquare
  this._fenEpSquare = old.fenEpSquare
  this._halfMoves = old.halfMoves
  this._moveNumber = old.moveNumber

  this._hash ^= this._epKey()
  this._hash ^= this._castlingKey()
  this._hash ^= SIDE_KEY

  const us = this._turn
  const them = swapColor(us)

  if (move.flags & BITS.NULL_MOVE) {
    return move
  }

  this._movePiece(move.to, move.from)

  // to undo any promotions
  if (move.piece) {
    this._clear(move.from)
    this._set(move.from, { type: move.piece, color: us })
